/// nothing to worry about if you re-run `unicode.py` (for example, when updating Unicode.)
/// However, if you change the *actual structure* of the lookup tables (perhaps by editing the
/// `make_tables` function in `unicode.py`) you must ensure that this code reflects those changes.
// crate: unicode-width-0.2.2/src/tables.rs:176 lookup_width
function lookup_width(c: number): [number, WidthInfo] {
  const cp = c;

  const t1_offset = WIDTH_ROOT[cp >> 13]!;

  // Each sub-table in WIDTH_MIDDLE is 7 bits, and each stored entry is a byte,
  // so each sub-table is 128 bytes in size.
  // (Sub-tables are selected using the computed offset from the previous table.)
  const t2_offset = WIDTH_MIDDLE[t1_offset]![(cp >> 7) & 0x3f]!;

  // Each sub-table in WIDTH_LEAVES is 6 bits, but each stored entry is 2 bits.
  // This is accomplished by packing four stored entries into one byte.
  // So each sub-table is 2**(7-2) == 32 bytes in size.
  // Since this is the last table, each entry represents an encoded width.
  const packed_widths = WIDTH_LEAVES[t2_offset]![(cp >> 2) & 0x1f]!;

  // Extract the packed width
  const width = (packed_widths >> (2 * (cp & 0b11))) & 0b11;

  if (width < 3) {
    return [width, WidthInfo.DEFAULT];
  } else {
    if (c === 0xa) return [1, WidthInfo.LINE_FEED];
    if (c === 0x5dc) return [1, WidthInfo.HEBREW_LETTER_LAMED];
    if (c >= 0x622 && c <= 0x882) return [1, WidthInfo.JOINING_GROUP_ALEF];
    if (c >= 0x1780 && c <= 0x17af) return [1, WidthInfo.KHMER_COENG_ELIGIBLE_LETTER];
    if (c === 0x17d8) return [3, WidthInfo.DEFAULT];
    if (c === 0x1a10) return [1, WidthInfo.BUGINESE_LETTER_YA];
    if (c >= 0x2d31 && c <= 0x2d6f) return [1, WidthInfo.TIFINAGH_CONSONANT];
    if (c >= 0xa4fc && c <= 0xa4fd) return [1, WidthInfo.LISU_TONE_LETTER_MYA_NA_JEU];
    if (c === 0xfe01) return [0, WidthInfo.VARIATION_SELECTOR_1_2_OR_3];
    if (c === 0xfe0e) return [0, WidthInfo.VARIATION_SELECTOR_15];
    if (c === 0xfe0f) return [0, WidthInfo.VARIATION_SELECTOR_16];
    if (c === 0x10c03) return [1, WidthInfo.OLD_TURKIC_LETTER_ORKHON_I];
    if (c === 0x16d67) return [1, WidthInfo.KIRAT_RAI_VOWEL_SIGN_E];
    if (c === 0x16d68) return [1, WidthInfo.KIRAT_RAI_VOWEL_SIGN_AI];
    if (c >= 0x1f1e6 && c <= 0x1f1ff) return [1, WidthInfo.REGIONAL_INDICATOR];
    if (c >= 0x1f3fb && c <= 0x1f3ff) return [2, WidthInfo.EMOJI_MODIFIER];
    return [2, WidthInfo.EMOJI_PRESENTATION];
  }
}

/// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c`, or
/// `None` if `c` is a control character.
/// Ambiguous width characters are treated as narrow.
// crate: unicode-width-0.2.2/src/tables.rs:224 single_char_width
export function single_char_width(c: number): number | undefined {
  if (c < 0x7f) {
    if (c >= 0x20) {
      // U+0020 to U+007F (exclusive) are single-width ASCII codepoints
      return 1;
    } else {
      // U+0000 to U+0020 (exclusive) are control codes
      return undefined;
    }
  } else if (c >= 0xa0) {
    // No characters >= U+00A0 are control codes, so we can consult the lookup tables
    return lookup_width(c)[0];
  } else {
    // U+007F to U+00A0 (exclusive) are control codes
    return undefined;
  }
}

