    if (c >= 0x1780 && c <= 0x17af) return [1, WidthInfo.KHMER_COENG_ELIGIBLE_LETTER];
    if (c === 0x17d8) return [3, WidthInfo.DEFAULT];
    if (c === 0x1a10) return [1, WidthInfo.BUGINESE_LETTER_YA];
    if (c >= 0x2d31 && c <= 0x2d6f) return [1, WidthInfo.TIFINAGH_CONSONANT];
    if (c >= 0xa4fc && c <= 0xa4fd) return [1, WidthInfo.LISU_TONE_LETTER_MYA_NA_JEU];
    if (c >= 0xfe00 && c <= 0xfe02) return [0, WidthInfo.VARIATION_SELECTOR_1_2_OR_3];
    if (c === 0xfe0f) return [0, WidthInfo.VARIATION_SELECTOR_16];
